// Dedupe on the canonical article link.
// The draft log sheet is the source of truth: any link already logged there is skipped,
// even if the feed re-publishes the item with a changed guid or publish date (e.g. after a typo fix).
const feedItems = $('1. RSS Feed Trigger').all();
const seen = new Set($input.all().map(r => String(r.json.link || '').trim()).filter(Boolean));
return feedItems.filter(i => {
  const link = String(i.json.link || '').trim();
  return link && !seen.has(link);
});
